 skrol:{name:'Warkah',meaning:'Royal scroll',blurb:'A letter on a scroll between gilt rods, with a Jawi heading and a red seal, in the manner of old Malay royal letters. It unrolls.',f:{d:"'Cinzel', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
 gerbang:{name:'Gerbang',meaning:'Wrought-iron gates',blurb:'Laser-cut wrought-iron gates in gold, black or white. They swing open onto the card.',f:{d:"'Cormorant Garamond', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
 lakaran:{name:'Lakaran',meaning:'Venue sketch',blurb:'A pen-and-ink sketch of an old Malayan building above your names, drawn from a 1900s postcard.',f:{d:"'Cormorant Garamond', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
 telegram:{name:'Telegram',meaning:'Telegram',blurb:'An old telegram with typed strips and an URGENT stamp. Every line ends in STOP.',f:{d:"'Old Standard TT', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
 mancis:{name:'Mancis',meaning:'Matchbox',blurb:'A matchbox label that calls you a perfect match. The drawer slides out to open it.',f:{d:"'Jost', sans-serif",s:"'Abril Fatface', serif",b:"'Cormorant Garamond', serif"}},
 anyaman:{name:'Anyaman',meaning:'Woven mat',blurb:'A woven mengkuang mat with dyed diamond bands and an oval card in the middle.',f:{d:"'Cormorant Garamond', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
 tekat:{name:'Tekat',meaning:'Gold embroidery',blurb:'Raised gold-thread embroidery on velvet, like a pelamin cushion: a wreath around your initials.',f:{d:"'Cinzel', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
 label:{name:'Label',meaning:'Vintage labels',blurb:'Old apothecary labels and a ribbon banner on a dark ground. It arrives as a hanging tag.',f:{d:"'Cormorant Garamond', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
